/*
 * A257877  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 0
 *          and d(1) = 3.
 * https://oeis.org/A257877
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) generated by Rule 1 with a(1)=0, d(1)=3
 * Range:     u8 n <= 181, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   contains_ll
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The function a() computes the n-th term of OEIS A257877. */

#include <stddef.h>   /* size_t */
#include <stdbool.h>  /* bool */
#include "../utils/contains_ll.h"

#define MAX_N   200000   /* enough for n up to 10000 */

static seq_t aVals[MAX_N];            /* a(1)..a(MAX_N) */
static long long dVals[MAX_N];        /* d(1)..d(MAX_N) */
static size_t aSize = 0;              /* number of terms computed so far */
static size_t dSize = 0;              /* number of differences stored */

/* linear search for a seq_t value in an array */
static bool contains_seq(size_t cnt, const seq_t *arr, seq_t val)
{
    for (size_t i = 0; i < cnt; ++i)
        if (arr[i] == val)
            return true;
    return false;
}

/* Compute the n-th term (n >= 1). */
seq_t a(idx_t n)
{
    if (n == 0)  /* undefined for n=0, but return 0 to avoid UB */
        return (seq_t)0;

    /* lazy initialization */
    if (aSize == 0)
    {
        aVals[0] = (seq_t)0;     /* a(1) = 0 */
        aSize   = 1;
        dVals[0] = 3;            /* d(1) = 3 */
        dSize   = 1;
    }

    /* compute terms up to n if necessary */
    while (aSize < (size_t)n)
    {
        seq_t a_k = aVals[aSize - 1];
        long long a_k_ll = (long long)a_k;   /* trustworthy for our range */

        long long h = 0;       /* candidate difference */
        bool found = false;

        /* Step 1: try negative h values */
        if (a_k_ll > 1)           /* a_k must be >= 2 to have h negative */
        {
            for (long long hh = -1; hh >= -(a_k_ll - 1); --hh)
            {
                if (contains_ll(dSize, dVals, hh))
                    continue;   /* difference already used */

                long long sum_ll = a_k_ll + hh;
                seq_t a_next = (seq_t)sum_ll;

                if (contains_seq(aSize, aVals, a_next))
                    continue;   /* resulting a already used */

                h = hh;
                found = true;
                break;
            }
        }

        /* Step 2: if no suitable negative h, find smallest positive h */
        if (!found)
        {
            for (long long hh = 1; ; ++hh)
            {
                if (contains_ll(dSize, dVals, hh))
                    continue;

                long long sum_ll = a_k_ll + hh;
                seq_t a_next = (seq_t)sum_ll;

                if (contains_seq(aSize, aVals, a_next))
                    continue;

                h = hh;
                found = true;
                break;
            }
        }

        /* Append new terms */
        seq_t a_next = (seq_t)(a_k_ll + h);
        aVals[aSize++] = a_next;
        dVals[dSize++] = h;
    }

    return aVals[n - 1];
}
